# =====================
#   256 color Colors
# =====================

fg256 = []                  # FG
bg256 = []                  # BG
fg256d = []                 # FG Bold
bg256d = []                 # BG Bold

for i in range(16, 256):
    fg256.append(f"\033[38;5;{i}m")         # Foreground color
    bg256.append(f"\033[48;5;{i}m")         # Background color
    fg256d.append(f"\033[1;38;5;{i}m")      # Foreground bold
    bg256d.append(f"\033[1;48;5;{i}m")      # Background bold
